actor WireTap<Message: Sendable> {
  private var sinks: [AsyncStream<Message>.Continuation] = []
  private(set) var drops = 0

  func attach(buffering: Int = 1024) -> AsyncStream<Message> {
    let (stream, sink) = AsyncStream<Message>.makeStream(
      bufferingPolicy: .bufferingNewest(buffering))  // explicit overflow policy
    sinks.append(sink)
    return stream                                    // one stream, one iterator per tap
  }

  func copyToTaps(_ message: Message) {              // never waits on the analyzer
    for sink in sinks {
      switch sink.yield(message) {                   // returns immediately
      case .dropped, .terminated: drops += 1         // visible loss counter
      case .enqueued: break
      }
    }
  }
}

func publish(_ m: Message) async {                   // tap interposed on the channel
  await primary.send(m)                              // original, unmodified, first
  await tap.copyToTaps(m)                            // bounded copy; drops counted
}

let traffic = await tap.attach()                     // removable without touching sender
Task { for await m in traffic { analyzer.inspect(m) } }
